 check("category sheet hides and pauses native preview",()->{eval("window.dispatchEvent(new Event('TiviLoomNativeExit'))");waitJS("innerHeight>innerWidth && document.querySelector('#player').hidden");SystemClock.sleep(500);eval("document.querySelector('[data-tv=groups]').click()");waitFor(()->((android.view.View)field("root")).getVisibility()==android.view.View.INVISIBLE&&!playing());waitJS("(()=>{const p=document.querySelector('#groups').getBoundingClientRect(),h=document.querySelector('.phone-groups-heading').getBoundingClientRect();return p.top>=0&&p.bottom<=innerHeight&&h.top>=p.top&&h.bottom<=p.bottom})()");capture("premium-categories");eval("document.querySelector('[data-tv=groups]').click()");waitFor(()->((android.view.View)field("root")).getVisibility()==android.view.View.VISIBLE);require(onMain(()->!playing())&&decoder()==original,"Closing groups resumed or replaced playback");tap("previewPause");waitFor(()->playing());});
